using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests.Quality;

public class QualityTests
{
    private static readonly string ContentRoot =
        Path.Combine(AppContext.BaseDirectory, "Quality");

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNameCaseInsensitive = true
    };

    public static IEnumerable<object[]> GoldenCases()
    {
        var path = Path.Combine(ContentRoot, "golden.json");
        var json = File.ReadAllText(path);
        var cases = JsonSerializer.Deserialize<List<GoldenCase>>(json, JsonOptions)
            ?? throw new InvalidOperationException("golden.json could not be deserialized.");

        foreach (var c in cases)
        {
            yield return new object[] { c.Id, c };
        }
    }

    [Theory]
    [MemberData(nameof(GoldenCases))]
    public async Task EvalCase_MeetsQualityBar(string caseId, GoldenCase goldenCase)
    {
        // Load the rubric for context (available for custom evaluators)
        var rubricPath = Path.Combine(ContentRoot, "rubric.md");
        var rubric = File.Exists(rubricPath) ? await File.ReadAllTextAsync(rubricPath) : string.Empty;

        // Placeholder: replace with actual agent invocation against the AppHost
        var agentResponse = await InvokeAgentAsync(goldenCase.UserMessage);

        // Validate expected traits are present in the response
        foreach (var trait in goldenCase.ExpectedTraits)
        {
            Assert.True(
                agentResponse.Contains(trait, StringComparison.OrdinalIgnoreCase),
                $"Case '{caseId}': response missing expected trait '{trait}'.");
        }
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // TODO: Wire up to the running AppHost via Aspire.Hosting.Testing
        // and send the user message to the agentic endpoint.
        throw new NotImplementedException(
            "Connect this method to the agentic app endpoint provided by the AppHost.");
    }
}

public record GoldenCase
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public List<string> ExpectedTraits { get; init; } = new();
}

